  auto rec = nlohmann::json::parse(kSnapshotJson);
  hanabi::Game game = hanabi::logging::apply_snapshot(rec);
  // Forced endgame, Rule 3 ("sole holder of a blocking card"). One card is
  // left in the deck and will-bot67 holds BOTH copies of red 4, so no red 4
  // can ever be drawn and nobody else can play one. That makes r4 the only
  // route to the r5 still behind it, and the play is forced.
  //
  // Rule 2 does NOT cover this: it wants two SINGLETON-critical cards, and
  // holding both copies is exactly what makes `is_critical(r4)` false. Before
  // Rule 3 existed this turn came out as a discard.
  hanabi::PerformAction action = game.take_action();
  ASSERT_TRUE(std::holds_alternative<hanabi::PerformPlay>(action))
      << "sole holder of both r4 must play one, not discard or clue";
  EXPECT_EQ(std::get<hanabi::PerformPlay>(action).target, 7);
